WITH catalog_agg AS ( SELECT cs.cs_ship_mode_sk, SUM(cs.cs_net_profit) AS catalog_net_profit FROM catalog_sales cs GROUP BY cs.cs_ship_mode_sk ), web_agg AS ( SELECT ws.ws_ship_mode_sk, SUM(ws.ws_net_profit) AS web_net_profit FROM web_sales ws GROUP BY ws.ws_ship_mode_sk ), joined AS ( SELECT sm.sm_ship_mode_sk, sm.sm_type, COALESCE(ca.catalog_net_profit, 0) AS catalog_net_profit, COALESCE(wa.web_net_profit, 0) AS web_net_profit FROM ship_mode sm LEFT JOIN catalog_agg ca ON sm.sm_ship_mode_sk = ca.cs_ship_mode_sk LEFT JOIN web_agg wa ON sm.sm_ship_mode_sk = wa.ws_ship_mode_sk ), diff AS ( SELECT sm_ship_mode_sk, sm_type, catalog_net_profit, web_net_profit, web_net_profit - catalog_net_profit AS profit_diff, CASE WHEN catalog_net_profit = 0 THEN NULL WHEN (web_net_profit - catalog_net_profit) / catalog_net_profit >= 0.20 THEN 'Web > Catalog +20%' ELSE 'Normal' END AS profit_flag FROM joined ) SELECT sm_ship_mode_sk, sm_type, catalog_net_profit, web_net_profit, profit_diff, profit_flag, RANK() OVER (ORDER BY profit_diff DESC) AS profit_diff_rank, SUM(profit_diff) OVER (ORDER BY profit_diff DESC ROWS UNBOUNDED PRECEDING) AS cumulative_profit_diff FROM diff ORDER BY profit_diff_rank LIMIT 10
